//! The console's D3D12 objects slot by slot, as its driver has them: GameOS
//! `xgs12_10.dll` (10.0.26100.7901), the user-mode driver `d3d12_xs.dll`
//! loads on current consoles. Each table is the driver's final one, built at
//! start by its copy-chain initialisers (+0x1390..+0x27e0) into `.data`;
//! `rva` is the method's address in the driver, to read it by. Generated by
//! reading the driver (never part of the tree).
//!
//! `Const(v)`: the method only returns `v` (its stubs: +0x40e0 `E_NOTIMPL`,
//! +0x194e0 `S_OK`, +0xa1e60 `E_FAIL`, +0x4db30 `E_ACCESSDENIED`, +0x3e680
//! 1, +0x43c70 -1, +0xa900 `DXGI_ERROR_UNSUPPORTED`). `Void`: returns at
//! once (+0xa880). `Trap`: breaks into the debugger (+0x2e330), a method
//! retail titles cannot call. `Runtime`: filled when the device is made.
//! `Body`: anything else.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Kind {
    Const(u32),
    Void,
    Trap,
    Runtime,
    Body,
}

#[derive(Clone, Copy, Debug)]
pub(crate) struct Slot {
    pub(crate) kind: Kind,
    pub(crate) rva: u32,
}

const fn c(rva: u32, v: u32) -> Slot {
    Slot { kind: Kind::Const(v), rva }
}
const fn v(rva: u32) -> Slot {
    Slot { kind: Kind::Void, rva }
}
const fn t(rva: u32) -> Slot {
    Slot { kind: Kind::Trap, rva }
}
const fn r() -> Slot {
    Slot { kind: Kind::Runtime, rva: 0 }
}
const fn b(rva: u32) -> Slot {
    Slot { kind: Kind::Body, rva }
}

