/// The console's own methods ("x-methods") and the common object methods,
/// called through the layer's tables as a title calls them, against what
/// the driver's code returns (the function cited in each test).
#[cfg(test)]
mod x_methods {
    use crate::object::{self, E_INVALIDARG, E_NOTIMPL, HRESULT, Iid, S_OK, This, slot};

    fn queue_slot<F: Copy>(offset: usize) -> F {
        let f = crate::queue::NEWER_FUNCTIONS.0[offset / 8];
        // SAFETY: the caller names the slot's signature.
        unsafe { std::mem::transmute_copy(&f) }
    }

    /// Queue 0x90 GetTimestampFrequency: the driver's +0x19470 writes
    /// 0x5f21070 (99.75 MHz) and returns S_OK.
    #[test]
    fn queue_timestamp_frequency_is_the_consoles() {
        let f = queue_slot::<extern "system" fn(This, *mut u64) -> HRESULT>(0x90);
        let mut hz = 0;
        assert_eq!(f(std::ptr::null(), &mut hz), S_OK);
        assert_eq!(hz, 0x5f2_1070);
        assert_eq!(f(std::ptr::null(), std::ptr::null_mut()), E_INVALIDARG);
    }

    /// Queue 0xb8 SuspendX(flags) (+0x1b970 -> +0x68170) and 0xc0 ResumeX()
    /// (+0x1b780 -> +0x67d00): S_OK on a configured device.
    #[test]
    fn queue_suspend_and_resume_answer_s_ok() {
        let suspend = queue_slot::<extern "system" fn(This, u32) -> HRESULT>(0xb8);
        let resume = queue_slot::<extern "system" fn(This) -> HRESULT>(0xc0);
        assert_eq!(suspend(std::ptr::null(), 0), S_OK);
        assert_eq!(resume(std::ptr::null()), S_OK);
    }

    /// Queue 0x78, 0xd0 (+0xa880, void), 0x108 (+0x194e0, S_OK) and
    /// 0xa0..0xb0, 0x120 (+0x40e0, E_NOTIMPL), the driver's stubs.
    #[test]
    fn queue_stub_methods_answer_as_the_driver() {
        let f = queue_slot::<extern "system" fn() -> u32>(0x108);
        assert_eq!(f(), 0);
        for o in [0xa0, 0xa8, 0xb0, 0x120] {
            assert_eq!(queue_slot::<extern "system" fn() -> HRESULT>(o)(), E_NOTIMPL, "{o:#x}");
        }
        queue_slot::<extern "system" fn()>(0x78)();
        queue_slot::<extern "system" fn()>(0xd0)();
    }

    /// Device 0x38 GetNodeCount (+0x3e680: 1), 0x228 (+0x40e0: E_NOTIMPL),
    /// 0x1c0 and 0x210 (+0x4db30: E_ACCESSDENIED), 0x200 (+0x43c70: -1).
    #[test]
    fn device_constant_methods_answer_as_the_driver() {
        let d = crate::device::device();
        assert_eq!(slot::<extern "system" fn(This) -> u32>(d, 0x38)(d), 1);
        assert_eq!(slot::<extern "system" fn(This) -> HRESULT>(d, 0x228)(d), E_NOTIMPL);
        for o in [0x1c0, 0x210] {
            assert_eq!(slot::<extern "system" fn(This) -> u32>(d, o)(d), 0x8007_0005, "{o:#x}");
        }
        assert_eq!(slot::<extern "system" fn(This) -> u32>(d, 0x200)(d), u32::MAX);
    }

    type Variant = extern "system" fn(This, This, u32, *const u8, *const Iid, *mut This) -> HRESULT;

    /// Device 0x1b8 (+0x4d380) clears `out` first. With no base or no
    /// records for a count the layer answers E_INVALIDARG where the driver
    /// would fault; a base not made by 0x1c8 is not a variant it can make.
    #[test]
    fn device_pipeline_variant_checks_its_arguments() {
        let d = crate::device::device();
        let f = slot::<Variant>(d, 0x1b8);
        let mut out: This = 1 as This;
        assert_eq!(f(d, std::ptr::null(), 0, std::ptr::null(), std::ptr::null(), &mut out), E_INVALIDARG);
        assert!(out.is_null());
        out = 1 as This;
        assert_eq!(f(d, d, 1, std::ptr::null(), std::ptr::null(), &mut out), E_INVALIDARG);
        assert!(out.is_null());
        assert_eq!(f(d, d, 0, std::ptr::null(), std::ptr::null(), std::ptr::null_mut()), E_INVALIDARG);
    }

    /// A COM object that counts its references.
    #[repr(C)]
    struct Counted {
        table: *const *const (),
        refs: std::sync::atomic::AtomicU32,
    }
    extern "system" fn counted_add(this: *const Counted) -> u32 {
        // SAFETY: one of the test's.
        unsafe { &*this }.refs.fetch_add(1, std::sync::atomic::Ordering::Relaxed) + 1
    }
    extern "system" fn counted_release(this: *const Counted) -> u32 {
        // SAFETY: one of the test's.
        unsafe { &*this }.refs.fetch_sub(1, std::sync::atomic::Ordering::Relaxed) - 1
    }
    struct Tab([*const (); 3]);
    // SAFETY: function addresses.
    unsafe impl Sync for Tab {}
    static COUNTED: Tab = Tab([std::ptr::null(), counted_add as *const (), counted_release as *const ()]);

    /// SetPrivateDataInterface (+0x41e80): kept with a reference
    /// (+0xa4e80), replaced or removed (+0xa5390) with it released;
    /// GetPrivateData (+0xa5680) hands the pointer out with a reference.
    /// SetName (+0x194e0) answers S_OK.
    #[test]
    fn private_data_interfaces_hold_a_reference() {
        let mut fence = std::ptr::null();
        assert_eq!(crate::fence::create(std::ptr::null(), 0, 0, &crate::fence::FENCE_IIDS[0], &mut fence), S_OK);
        let set = slot::<extern "system" fn(This, *const Iid, *const Counted) -> HRESULT>(fence, 0x28);
        let get = slot::<extern "system" fn(This, *const Iid, *mut u32, *mut u8) -> HRESULT>(fence, 0x18);
        let name = slot::<extern "system" fn(This, *const u16) -> HRESULT>(fence, 0x30);
        let release = slot::<extern "system" fn(This) -> u32>(fence, 0x10);
        let id: Iid = [7; 16];
        let a = Counted { table: COUNTED.0.as_ptr(), refs: 1.into() };
        let b = Counted { table: COUNTED.0.as_ptr(), refs: 1.into() };
        let refs = |c: &Counted| c.refs.load(std::sync::atomic::Ordering::Relaxed);
        assert_eq!(set(fence, &id, &a), S_OK);
        assert_eq!(refs(&a), 2);
        let mut size = 8u32;
        let mut bytes = [0u8; 8];
        assert_eq!(get(fence, &id, &mut size, bytes.as_mut_ptr()), S_OK);
        assert_eq!(usize::from_le_bytes(bytes), &a as *const Counted as usize);
        assert_eq!(refs(&a), 3);
        assert_eq!(set(fence, &id, &b), S_OK);
        assert_eq!((refs(&a), refs(&b)), (2, 2));
        assert_eq!(set(fence, &id, std::ptr::null()), S_OK);
        assert_eq!(refs(&b), 1);
        assert_eq!(set(fence, &id, &b), S_OK);
        assert_eq!(set(fence, std::ptr::null(), &b), E_INVALIDARG);
        assert_eq!(name(fence, std::ptr::null()), S_OK);
        assert_eq!(release(fence), 0);
        assert_eq!(refs(&b), 1, "the last release lets go of the interfaces");
        let _ = object::ignore;
    }
}

/// Timings of the D3D12 paths the title calls most, through the layer's
/// tables. Run by hand in a release build:
/// `cargo test --release -p victory-gpu --lib bench_d3d12 -- --ignored --nocapture`.
#[cfg(test)]
mod bench_d3d12 {
    use crate::object::{Iid, S_OK, This, slot};
    use std::hint::black_box;
    use std::time::Instant;

    fn report(what: &str, n: usize, f: impl FnMut(usize)) {
        let mut f = f;
        let mut samples = [0.0f64; 5];
        for s in &mut samples {
            let start = Instant::now();
            for i in 0..n {
                f(i);
            }
            *s = start.elapsed().as_secs_f64() * 1e9 / n as f64;
        }
        samples.sort_by(f64::total_cmp);
        println!("{what:44} {:9.1} ns/call (median of 5 x {n})", samples[2]);
    }

    #[test]
    #[ignore = "benchmark: run by hand, in a release build"]
    fn bench_d3d12_descriptor_views() {
        let d = crate::device::device();
        let cbv = slot::<extern "system" fn(This, *const [u32; 4], u64)>(d, 0x88);
        let srv = slot::<extern "system" fn(This, This, *const [u32; 10], u64)>(d, 0x90);
        let mut slots = vec![[0u64; 4]; 4096];
        let base = slots.as_mut_ptr() as u64;
        report("device 0x88 CreateConstantBufferView", 1 << 20, |i| {
            let desc = [0x1000_0000u32 + ((i as u32 & 1023) << 8), 0x2, 256, 0];
            cbv(d, &desc, base + 32 * (i as u64 & 4095));
        });
        let desc = [28u32, 4, 0x1688, 0, 1, 0, 0, 0, 0, 0];
        report("device 0x90 CreateShaderResourceView", 1 << 20, |i| {
            srv(d, (0x5000_0000 + (i & 255) * 0x100) as This, &desc, base + 32 * (i as u64 & 4095));
        });
        black_box(&slots);
    }

    #[test]
    #[ignore = "benchmark: run by hand, in a release build"]
    fn bench_d3d12_private_data() {
        let mut fence = std::ptr::null();
        assert_eq!(crate::fence::create(std::ptr::null(), 0, 0, &crate::fence::FENCE_IIDS[0], &mut fence), S_OK);
        let set = slot::<extern "system" fn(This, *const Iid, u32, *const u8) -> i32>(fence, 0x20);
        let get = slot::<extern "system" fn(This, *const Iid, *mut u32, *mut u8) -> i32>(fence, 0x18);
        let id: Iid = [9; 16];
        set(fence, &id, 8, [1u8; 8].as_ptr());
        let mut out = [0u8; 8];
        report("GetPrivateData (8 bytes)", 1 << 20, |_| {
            let mut size = 8;
            black_box(get(fence, &id, &mut size, out.as_mut_ptr()));
        });
        report("SetPrivateData (8 bytes)", 1 << 20, |i| {
            black_box(set(fence, &id, 8, (i as u64).to_le_bytes().as_ptr()));
        });
    }

    #[cfg(windows)]
    #[test]
    #[ignore = "benchmark: run by hand, in a release build"]
    fn bench_d3d12_pipeline_variants() {
        let regs: Vec<u8> = {
            let mut w = vec![0u32; 0x184 / 4];
            w[31] = 0x00cc_0010;
            w.iter().flat_map(|x| x.to_le_bytes()).collect()
        };
        let mut base: This = std::ptr::null();
        let iid = crate::pipeline::PIPELINE_IIDS[0];
        assert_eq!(crate::pipeline::hand_out_native_graphics(Vec::new(), regs, vec![0; 0x60], &iid, &mut base), S_OK);
        let d = crate::device::device();
        let f = slot::<extern "system" fn(This, This, u32, *const u8, *const Iid, *mut This) -> i32>(d, 0x1b8);
        let mut records = vec![0u8; 2 * crate::pipeline::variant::RECORD];
        records[crate::pipeline::variant::RECORD..][..4].copy_from_slice(&2u32.to_le_bytes());
        report("device 0x1b8 pipeline variant (kinds 0, 2) + release", 1 << 14, |_| {
            let mut v: This = std::ptr::null();
            assert_eq!(f(d, base, 2, records.as_ptr(), &iid, &mut v), S_OK);
            let release = slot::<extern "system" fn(This) -> u32>(v, 0x10);
            black_box(release(v));
        });
    }
}
